values
('camping', 'Camping', '999', 'per person', '', 'Trade city lights for starry skies and the simple joy of sleeping outdoors.', '/media/tents-comp.png', 'tent', 'Tent Camping Package', 'Exclusive tent stay', ARRAY['Exclusive tent accommodation', 'Bonfire', 'Welcome snacks and tea', 'Limited BBQ — vegetarian and non-vegetarian', 'Unlimited dinner — vegetarian and non-vegetarian', 'Breakfast and tea before checkout', 'Swimming pool and boating', 'Music and dance floor', 'Kids play area', 'Indoor games: chess, carrom, darts and archery', 'Outdoor games: cricket, badminton, table tennis and fishing'], 0, true),
('container', 'Container Room', '3300', 'per couple', 'A different kind of escape', 'A unique space to unwind, with a little more room between you and the everyday.', '/media/container-rooms-comp.png', 'home', 'Container Room Package', 'Container room stay for a couple', ARRAY['Container room accommodation for a couple', 'Bonfire', 'Welcome snacks and tea', 'Limited BBQ — vegetarian and non-vegetarian', 'Unlimited dinner — vegetarian and non-vegetarian', 'Breakfast and tea before checkout', 'Swimming pool and boating', 'Music and dance floor', 'Kids play area', 'Indoor games: chess, carrom, darts and archery', 'Outdoor games: cricket, badminton, table tennis and fishing'], 1, true),
('villa', 'Villa''s with private Bonfire', '1899', 'per person', 'Make room for everyone', 'Bring your favourite people together for an easy, unhurried getaway with a private bonfire.', '/media/Villa-comp.png', 'home', 'Waterfront Villa Package', 'Waterfront villa stay with a private bonfire', ARRAY['Waterfront villa accommodation', 'Private bonfire', 'Welcome snacks and tea', 'Limited BBQ — vegetarian and non-vegetarian', 'Unlimited dinner — vegetarian and non-vegetarian', 'Breakfast and tea before checkout', 'Swimming pool and boating', 'Music and dance floor', 'Kids play area', 'Indoor games: chess, carrom, darts and archery', 'Outdoor games: cricket, badminton, table tennis and fishing'], 2, true),
('glamping', 'Glamping Tents', '1359', 'per person', 'The best of both worlds', 'The spirit of camping, with a more comfortable place to call it a night.', '/media/glamping-tents-comp.png', 'tent', 'Glamping Tent Package', 'Glamping tent stay', ARRAY['Glamping tent accommodation', 'Bonfire', 'Welcome snacks and tea', 'Limited BBQ — vegetarian and non-vegetarian', 'Unlimited dinner — vegetarian and non-vegetarian', 'Breakfast and tea before checkout', 'Swimming pool and boating', 'Music and dance floor', 'Kids play area', 'Indoor games: chess, carrom, darts and archery', 'Outdoor games: cricket, badminton, table tennis and fishing'], 3, true)
