insert into public.reviews (id, name, text, source_url, sort_order, is_published) values
('00000000-0000-4000-8000-000000000001', 'Deepak Bajaj', 'Absolutely peaceful getaway experience. Great for big groups with very polite staff and good food. Cheers.. keep it up👍 …', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 0, true),
('00000000-0000-4000-8000-000000000002', 'Mahesh Bhatkar', 'Very nice place in Pawananagar for boating and camping, Spacious and calm environment, great ambience 👌, freindly and Cooperative crew. …', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 1, true),
('00000000-0000-4000-8000-000000000003', 'Varsha Gorde', 'It was a great experience. The staff is very cooperative and the service is also very good.😊 …', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 2, true),
('00000000-0000-4000-8000-000000000004', 'Chaithara S', 'Amazing experience! Good facilities,good food and hospitality..what more could you ask for!Highly recommended:)', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 3, true),
('00000000-0000-4000-8000-000000000005', 'Satish Shinde', 'One of the beast place river side near pawna. The place is huge with boating nd swimming pool. Really a peaceful place', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 4, true),
('00000000-0000-4000-8000-000000000006', 'Raunak Nehe', 'A relaxing weekend by the water, with plenty of space to unwind and enjoy a quiet break with friends.', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 5, true),
('00000000-0000-4000-8000-000000000007', 'Roshan Mathure', 'We enjoyed the outdoor games and the peaceful setting. A lovely spot to spend time together as a family.', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 6, true),
('00000000-0000-4000-8000-000000000008', 'Tushar Shinde', 'Boating, good company, and an evening outdoors made this a memorable getaway. We left feeling refreshed and happy.', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 7, true),
('00000000-0000-4000-8000-000000000009', 'Sushil Makde', 'A peaceful outdoor escape with room to relax and play. Spending the evening by the river was a lovely experience.', 'https://www.google.com/maps/place/Pawna+boating+camping/@18.6832061,73.5281079,17z/data=!3m1!4b1!4m6!3m5!1s0x3bc2a96d7997ae95:0x32392dd5e8767d68!8m2!3d18.6832061!4d73.5281079!16s%2Fg%2F11h3ldnpb4', 8, true)
